// generated by the big ai

import { expect, test, type Locator, type Page } from "@playwright/test";
import type { KeySize, KeyVariant, Theme } from "..";
import type { KeyStoryProps, StoryName } from "./harness/stories";
import {
  centreY,
  contrast,
  faceColor,
  luminance,
  measureKeyInk,
  paintedBottom,
  parseRgb,
} from "./ink";

// Specs run in Node and can't load the component module (it imports CSS).
const keyVariants = [
  "primary",
  "quiet",
  "on-mask",
] as const satisfies readonly KeyVariant[];
const keySizes = ["md", "sm"] as const satisfies readonly KeySize[];

async function open(
  page: Page,
  story: StoryName,
  props: KeyStoryProps = {},
  theme: Theme = "paper",
) {
  const query = new URLSearchParams({
    story,
    theme,
    props: JSON.stringify(props),
  });
  await page.goto(`/?${query}`);
  await page.evaluate(() => document.fonts.ready.then(() => undefined));
}

async function mountKey(page: Page, props?: KeyStoryProps, theme?: Theme) {
  await open(page, "key", props, theme);
  return page.getByRole("button");
}

const clicks = (page: Page) => page.evaluate(() => window.keyClicks);

// Face offset from rest and how much lip shows below it, in CSS px.
const keycap = (key: Locator) =>
  key.evaluate((el) => {
    const button = el.getBoundingClientRect();
    const face = el.querySelector(".key__face")!.getBoundingClientRect();
    const base = getComputedStyle(el, "::before");
    const baseBottom =
      base.display === "none"
        ? face.bottom
        : button.bottom - parseFloat(base.bottom);
    return { face: face.top - button.top, lip: baseBottom - face.bottom };
  });

// Resolves a token the way the page sees it, e.g. "var(--rule)" -> "rgb(...)".
const resolve = (page: Page, property: string, value: string) =>
  page.evaluate(
    ([property, value]) => {
      const probe = document.createElement("div");
      probe.style.setProperty(property, value);
      document.body.append(probe);
      const resolved = getComputedStyle(probe).getPropertyValue(property);
      probe.remove();
      return resolved;
    },
    [property, value],
  );

test.describe("behaviour", () => {
  test("is a plain button named by its label", async ({ page }) => {
    const key = await mountKey(page);
    await expect(key).toHaveAccessibleName("Join the club");
    await expect(key).toHaveAttribute("type", "button");
  });

  test("passes native button props through", async ({ page }) => {
    const key = await mountKey(page, { type: "submit", title: "Join" });
    await expect(key).toHaveAttribute("type", "submit");
    await expect(key).toHaveAttribute("title", "Join");
  });

  test("activates by pointer and keyboard", async ({ page }) => {
    const key = await mountKey(page);
    await key.click();
    await key.press("Enter");
    await key.press("Space");
    expect(await clicks(page)).toBe(3);
  });

  test("ignores activation when disabled", async ({ page }) => {
    const key = await mountKey(page, { disabled: true });
    await expect(key).toBeDisabled();
    await key.click({ force: true });
    expect(await clicks(page)).toBe(0);
  });
});

test.describe("loading", () => {
  test("is busy, stays focusable and keeps its name", async ({ page }) => {
    const key = await mountKey(page, { loading: true });
    await expect(key).toHaveAttribute("aria-busy", "true");
    await expect(key).toHaveAttribute("aria-disabled", "true");
    await expect(key).toHaveAccessibleName("Join the club");
    await expect(key).toHaveJSProperty("disabled", false);
    await key.focus();
    await expect(key).toBeFocused();
  });

  test("blocks repeated activation", async ({ page }) => {
    const key = await mountKey(page, { loading: true });
    await key.click({ force: true });
    await key.press("Enter");
    await key.press("Space");
    expect(await clicks(page)).toBe(0);
  });

  test("announces a status message", async ({ page }) => {
    await mountKey(page);
    await expect(page.getByRole("status")).toHaveText("");

    await mountKey(page, { loading: true, loadingLabel: "Joining" });
    await expect(page.getByRole("status")).toHaveText("Joining");
  });

  test("keeps the key's width", async ({ page }) => {
    for (const size of keySizes) {
      const idle = await (await mountKey(page, { size })).boundingBox();
      const busy = await (
        await mountKey(page, { size, loading: true })
      ).boundingBox();
      expect(busy!.width).toBe(idle!.width);
    }
  });

  test("animates the progress pixels", async ({ page }) => {
    await mountKey(page, { loading: true });
    await expect(page.locator(".key__progress > span").first()).toHaveCSS(
      "animation-name",
      "key-progress",
    );
  });

  test("holds the progress pixels still for reduced motion", async ({
    page,
  }) => {
    await page.emulateMedia({ reducedMotion: "reduce" });
    await mountKey(page, { loading: true });
    const pixels = page.locator(".key__progress > span");
    await expect(pixels.first()).toHaveCSS("animation-name", "none");
    await expect(pixels.nth(0)).toHaveCSS("opacity", "1");
    await expect(pixels.nth(1)).toHaveCSS("opacity", "0.5");
    await expect(pixels.nth(2)).toHaveCSS("opacity", "0.25");
  });
});

/*
 * Keycap motion. The face slides over a fixed base and the base's bottom
 * edge never moves: hover lifts the face 2px (5px of lip showing), press
 * sinks it 3px onto the base (no lip), release springs back.
 */
test.describe("states", () => {
  // Transitions off so each state can be measured as soon as it applies.
  test.use({ reducedMotion: "reduce" });

  for (const variant of keyVariants) {
    test(`${variant} lifts on hover and sinks on press`, async ({ page }) => {
      const key = await mountKey(page, { variant });
      const bottom = await paintedBottom(key);
      expect(bottom, "lip bottom at rest").toBe(
        (await key.boundingBox())!.height + 3,
      );
      await expect.poll(() => keycap(key)).toEqual({ face: 0, lip: 3 });

      await key.hover();
      await expect.poll(() => keycap(key)).toEqual({ face: -2, lip: 5 });
      expect(await paintedBottom(key), "lip bottom on hover").toBe(bottom);

      await page.mouse.down();
      await expect.poll(() => keycap(key)).toEqual({ face: 3, lip: 0 });
      expect(await paintedBottom(key), "lip bottom on press").toBe(bottom);

      await page.mouse.up();
      await expect.poll(() => keycap(key)).toEqual({ face: -2, lip: 5 });
    });
  }

  for (const theme of ["paper", "mask"] as const) {
    for (const variant of keyVariants) {
      test(`${variant} lightens on hover and darkens on press on ${theme}`, async ({
        page,
      }) => {
        const key = await mountKey(page, { variant }, theme);
        const label = parseRgb(
          await key.evaluate((el) => getComputedStyle(el).color),
        );
        const rest = await faceColor(key);

        await key.hover();
        await expect
          .poll(async () => luminance(await faceColor(key)))
          .toBeGreaterThan(luminance(rest));
        const hover = await faceColor(key);

        await page.mouse.down();
        await expect
          .poll(async () => luminance(await faceColor(key)))
          .toBeLessThan(luminance(rest));
        const press = await faceColor(key);
        await page.mouse.up();

        for (const [state, face] of Object.entries({ rest, hover, press })) {
          expect(
            contrast(face, label),
            `label contrast on ${state} face rgb(${face})`,
          ).toBeGreaterThanOrEqual(4.5);
        }
      });
    }
  }

  test("pressing near the top edge still clicks", async ({ page }) => {
    const key = await mountKey(page);
    const box = (await key.boundingBox())!;
    await page.mouse.click(box.x + box.width / 2, box.y + 1);
    expect(await clicks(page)).toBe(1);
  });

  test("shows the focus ring for keyboard focus", async ({
    page,
    browserName,
  }) => {
    const key = await mountKey(page);
    // Safari only tabs to buttons with Option held (or "Press Tab to
    // highlight each item" turned on).
    await page.keyboard.press(browserName === "webkit" ? "Alt+Tab" : "Tab");
    await expect(key).toBeFocused();
    await expect(key.locator(".key__face")).toHaveCSS(
      "box-shadow",
      await resolve(page, "box-shadow", "var(--focus-shadow)"),
    );
  });

  test("disabled is flat and doesn't move", async ({ page }) => {
    const key = await mountKey(page, { disabled: true });
    await expect.poll(() => keycap(key)).toEqual({ face: 0, lip: 0 });
    await key.hover({ force: true });
    await page.mouse.down();
    await expect.poll(() => keycap(key)).toEqual({ face: 0, lip: 0 });
  });

  test("loading doesn't move", async ({ page }) => {
    const key = await mountKey(page, { loading: true });
    await key.hover({ force: true });
    await expect.poll(() => keycap(key)).toEqual({ face: 0, lip: 3 });
    await page.mouse.down();
    await expect.poll(() => keycap(key)).toEqual({ face: 0, lip: 3 });
  });
});

test.describe("motion", () => {
  test("eases the face between states", async ({ page }) => {
    const face = (await mountKey(page)).locator(".key__face");
    await expect(face).toHaveCSS(
      "transition-property",
      "transform, background-color",
    );
    await expect(face).toHaveCSS("transition-duration", "0.4s");
  });

  test("snaps between states for reduced motion", async ({ page }) => {
    await page.emulateMedia({ reducedMotion: "reduce" });
    const face = (await mountKey(page)).locator(".key__face");
    await expect(face).toHaveCSS("transition-duration", "0s");
  });
});

/*
 * Optical spacing, measured from rendered pixels.
 *
 * The visible content (pad + glyphs) must sit 1px above the key's true
 * centre (~2% of its height; the geometric centre reads as low), with equal
 * visible insets left and right and an 8px pad-to-label gap.
 *
 * MD (Departure Mono, whole-pixel metrics) lands within 0.25px everywhere.
 * SM (Redaction, 15px) gets more slack: its 13.5px ascent is rounded per
 * engine, so Chromium draws it 0.5px higher than Firefox and WebKit, and the
 * last glyph's side bearing (e.g. "b") adds up to 0.5px on the right.
 */
test.describe("optical spacing", () => {
  const LIFT = 1;
  const SLACK = { md: 0.5, sm: 0.75 };

  for (const variant of keyVariants) {
    for (const size of keySizes) {
      test(`${variant} ${size}`, async ({ page }) => {
        const ink = await measureKeyInk(
          await mountKey(page, { variant, size }),
        );
        const slack = SLACK[size];
        const opticalCentre = ink.height / 2 - LIFT;
        const left = (ink.pad ?? ink.text).left;
        const right = ink.width - ink.text.right;

        expect(
          Math.abs(centreY(ink.text) - opticalCentre),
          `label centre ${centreY(ink.text)} vs optical centre ${opticalCentre}`,
        ).toBeLessThan(slack);
        expect(
          Math.abs(left - right),
          `visible insets ${left} | ${right}`,
        ).toBeLessThan(slack);
        if (ink.pad) {
          expect(
            Math.abs(centreY(ink.pad) - opticalCentre),
            `pad centre ${centreY(ink.pad)} vs optical centre ${opticalCentre}`,
          ).toBeLessThan(0.5);
          expect(
            Math.abs(ink.text.left - ink.pad.right - 8),
            `pad-to-label gap ${ink.text.left - ink.pad.right}`,
          ).toBeLessThan(slack);
        }
      });

      test(`${variant} ${size} disabled stays centred at the same width`, async ({
        page,
      }) => {
        const enabled = await (
          await mountKey(page, { variant, size })
        ).boundingBox();
        const ink = await measureKeyInk(
          await mountKey(page, { variant, size, disabled: true }),
        );
        const slack = SLACK[size];

        const left = ink.text.left;
        const right = ink.width - ink.text.right;
        const opticalCentre = ink.height / 2 - LIFT;

        expect(ink.pad).toBeUndefined();
        expect(ink.width).toBe(enabled!.width);
        expect(
          Math.abs(left - right),
          `visible insets ${left} | ${right}`,
        ).toBeLessThan(slack);
        expect(
          Math.abs(centreY(ink.text) - opticalCentre),
          `label centre ${centreY(ink.text)} vs optical centre ${opticalCentre}`,
        ).toBeLessThan(slack);
      });
    }
  }
});

test.describe("visual", () => {
  for (const theme of ["paper", "mask"] as const) {
    test(`matrix on ${theme}`, async ({ page }) => {
      await open(page, "key-matrix", {}, theme);
      await expect(page.locator("#root")).toHaveScreenshot(
        `key-matrix-${theme}.png`,
      );
    });
  }
});
